def snapshot(root):
    result = {}
    for path in [root, *sorted(root.rglob('*'))]:
        s = path.lstat()
        value = [s.st_mode, s.st_size if not path.is_dir() else None,
                 s.st_mtime_ns if not path.is_dir() else None]
        if path.is_symlink():
            value.append(os.readlink(path))
        elif path.is_file():
            try:
                value.append(hashlib.sha256(path.read_bytes()).hexdigest())
            except PermissionError:
                value.append('unreadable')
        result[str(path.relative_to(root))] = value
    return result


def seal(root):
    entries = list(root.rglob('*'))
    assert len(entries) <= 100 and all(len(p.relative_to(root).parts) <= 8 for p in entries)
    for p in entries:
        mode = p.lstat().st_mode
        assert stat.S_ISREG(mode) or stat.S_ISDIR(mode) or stat.S_ISLNK(mode)
        if p.is_symlink():
            continue
        if p.is_file():
            assert p.stat().st_size <= 1_048_577
            p.chmod(p.stat().st_mode & ~0o222)
    for p in reversed(entries):
        if not p.is_symlink() and p.is_dir():
            p.chmod(p.stat().st_mode & ~0o222)
    root.chmod(root.stat().st_mode & ~0o222)


