@pytest.mark.parametrize('artifacts', [False, True])
def test_native_fixture_oracles(environment, name, artifacts):
    f = environment
    spec = fixture_tree(f, name)
    before = snapshot(f['input_root'])
    plan = adapter.prepare_inventory(input_root=f['input_root'], cwd=f['cwd'], include_artifacts=artifacts)
    catalog = adapter.collect_catalog(plan)
