@pytest.mark.parametrize('name', ['empty','plain','completed','unicode_csv','json_cap','oversized'])
@pytest.mark.parametrize('artifacts', [False,True])
def test_native_publication_bytes(environment, name, artifacts):
    f = environment
    spec = fixture_tree(f,name)
    before = snapshot(f['input_root'])
    plan = adapter.prepare_catalog_build(**arguments(f),include_artifacts=artifacts)
    catalog = adapter.collect_catalog(plan.inventory)
    assert_oracle(spec,catalog,artifacts)
    result = adapter.publish_catalog(plan,catalog)
    names = ['catalog.json','datasets.csv']+(['artifacts.csv'] if artifacts and catalog['file_count'] else [])
    assert result.complete and result.published_files == result.expected_files
    assert sorted(p.name for p in result.output_dir.iterdir()) == sorted(names)
    assert (result.output_dir/'catalog.json').read_bytes() == (json.dumps(catalog,indent=2,ensure_ascii=False,allow_nan=False)+'\n').encode()
    # Independent stdlib CSV oracle: fixed native columns and explicit cell rules.
    for name, rows, columns in [('datasets.csv',catalog['datasets'],native.DATASET_COLUMNS),
                                ('artifacts.csv',catalog['artifacts'],native.ARTIFACT_COLUMNS)]:
        if name not in names:
            continue
        stream = io.StringIO(newline='')
        writer = csv.DictWriter(stream,fieldnames=columns,lineterminator='\r\n')
        writer.writeheader()
        writer.writerows({k:json.dumps(v,ensure_ascii=False,sort_keys=True) if isinstance(v,(dict,list)) else v
                          for k,v in row.items()} for row in rows)
        assert (result.output_dir/name).read_bytes() == stream.getvalue().encode()
    assert snapshot(f['input_root']) == before


