def test_late_competitor_collision_preserves_winner(environment,monkeypatch):
    f=environment;seal(f['input_root']);original=native.write_catalog
    def competing(catalog,directory,**kw):
        original(catalog,directory,**kw)
        original(catalog,directory,**kw)
    monkeypatch.setattr(native,'write_catalog',competing)
    status,text,error=invoke(f)
    assert status==1 and not text and 'unattributed' in error
    d=f['output_root']/'catalog'
    assert json.loads((d/'catalog.json').read_text())['file_count']==0
    assert sorted(p.name for p in d.iterdir())==['catalog.json','datasets.csv']


def test_inspection_unknown_and_no_follow(environment,monkeypatch):
    f=environment;seal(f['input_root']);plan=adapter.prepare_catalog_build(**arguments(f))
    catalog=adapter.collect_catalog(plan.inventory)
    def faulty_write(*args,**kw):
        plan.output_dir.mkdir();plan.output_dir.chmod(0);raise PermissionError(13,'denied')
    monkeypatch.setattr(native,'write_catalog',faulty_write)
    with pytest.raises(adapter.PublicationFailure) as caught:adapter.publish_catalog(plan,catalog)
    assert caught.value.inspection_errors
    assert all(s=='unknown' for p,s in caught.value.observed_paths if p!=plan.output_dir)
    # Observer's direct no-follow check uses a different, caller-owned D.
    alias=f['output_root']/'alias';alias.symlink_to(f['input_root'])
    observed,errors=adapter._observe(alias)
    assert observed[0][1]=='symlink' and all(s=='unknown' for p,s in observed[1:]) and not errors


def test_reporting_failure_preserves_completed_publication(environment):
    f=environment;seal(f['input_root'])
    class Broken:
        def write(self,text):raise OSError('stdout unavailable')
    error=io.StringIO()
    assert adapter.catalog_build(**arguments(f),stdout=Broken(),stderr=error)==1
    assert 'reporting' in error.getvalue() and 'publication_complete=True' in error.getvalue()
    assert sorted(p.name for p in (f['output_root']/'catalog').iterdir())==['catalog.json','datasets.csv']


