def test_public_routes_remain_unavailable_and_parser_unchanged(environment,capsys):
    from nek_post.cli import main
    f=environment;seal(f['input_root'])
    with pytest.raises(SystemExit) as help_exit:main(['results','inventory','--help'])
    assert help_exit.value.code==0
    with pytest.raises(SystemExit) as parse_exit:main(['results','inventory','--artifacts'])
    assert parse_exit.value.code==2
    with pytest.raises(SystemExit) as unknown_exit:main(['results','inventory','--invented'])
    assert unknown_exit.value.code==2
    assert main(['results','inventory','--input-root',str(f['input_root'])])==3
    assert main(['results','catalog','build','--input-root',str(f['input_root']),
                 '--output-root',str(f['output_root']),'--paths-config',str(f['paths_config'])])==3
    assert not list(f['output_root'].iterdir())
